import React, { useState, useEffect } from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import Modal from '../../../components/ui/Modal/Modal';
import Button from '../../../components/ui/Button/Button';
import InputField from '../../../components/ui/InputField/InputField';
import api from '../../../api/api';
import styles from './AcceptancePage.module.css';

const AcceptancePage = ({ user }) => {
  const [proofs, setProofs] = useState([]);
  const [selectedProof, setSelectedProof] = useState(null);
  const [isApproveModalOpen, setApproveModalOpen] = useState(false);
  const [sealsToAward, setSealsToAward] = useState(10); // Valor padrão

  const fetchProofs = async () => {
    if (user && user.ong_id) {
      try {
        const response = await api.get(`/proofs/pending/${user.ong_id}`);
        setProofs(response.data);
      } catch (error) {
        console.error("Erro ao buscar provas pendentes:", error);
      }
    }
  };

  useEffect(() => {
    fetchProofs();
  }, [user]);

  const handleApproveClick = (proof) => {
    setSelectedProof(proof);
    setApproveModalOpen(true);
  };

  const handleReject = async (proofId) => {
    try {
      await api.put(`/proofs/${proofId}/reject`);
      fetchProofs(); // Atualiza a lista
    } catch (error) {
      console.error("Erro ao rejeitar prova:", error);
    }
  };

  const confirmApproval = async (e) => {
    e.preventDefault();
    try {
      await api.put(`/proofs/${selectedProof.id}/approve`, { sealsToAward });
      setApproveModalOpen(false);
      fetchProofs(); // Atualiza a lista
    } catch (error) {
      console.error("Erro ao aprovar prova:", error);
    }
  };

  return (
    <ContentWrapper title="Tela de Aceite de Provas Sociais">
      <ul className={styles.list}>
        {proofs.length > 0 ? proofs.map(proof => (
          <li key={proof.id} className={styles.listItem}>
            <div>
              <p className={styles.userName}>{proof.userName}</p>
              <p className={styles.action}>{proof.title}</p>
            </div>
            <div className={styles.buttons}>
              <button className={`${styles.button} ${styles.approve}`} onClick={() => handleApproveClick(proof)}>Aprovar</button>
              <button className={`${styles.button} ${styles.reject}`} onClick={() => handleReject(proof.id)}>Rejeitar</button>
            </div>
          </li>
        )) : <p>Nenhuma prova social pendente.</p>}
      </ul>

      {/* Modal de Aprovação */}
      <Modal 
        isOpen={isApproveModalOpen} 
        onClose={() => setApproveModalOpen(false)} 
        title="Aprovar Prova Social"
      >
        {selectedProof && (
          <form onSubmit={confirmApproval}>
            <p>Quantos selos deseja atribuir a <strong>{selectedProof.userName}</strong> pela ação "{selectedProof.title}"?</p>
            <InputField 
              label="Quantidade de Selos"
              type="number"
              value={sealsToAward}
              onChange={(e) => setSealsToAward(e.target.value)}
            />
            <div className={styles.modalActions}>
              <Button variant="secondary" type="button" onClick={() => setApproveModalOpen(false)}>Cancelar</Button>
              <Button type="submit">Confirmar Aprovação</Button>
            </div>
          </form>
        )}
      </Modal>
    </ContentWrapper>
  );
};

export default AcceptancePage;
